function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var PK='Kyle wrote that “significance” is in the eye of the beholder, and AI “is not particularly good at assessing it.” I am, and I keep the receipts.';
var PC='When I tell you no on a hatch, you get the test that would reopen it.';
var PL=[['Regulated products','10','SEC and FINRA regulated, at Grayscale: a $7B portfolio'],['Zero to one','$0 → $2M+','Co-founded; profitable in 24 months. Earlier, GM of a video ad network'],['Claims, public record','28 of 37','Each linked to its record: 8 on request, 1 not yet shown'],['Beliefs killed','48','By a runnable test since June; 20 became rules I now work by']];
function kitPlk(host,n,frame){var w=document.createElement('div');w.className='plk';var h='';if(frame)h+='<p class="plk-kick">'+kEsc(PK)+'</p>';h+='<ul class="plk-cells">'+PL.slice(0,n).map(function(c){return '<li class="plk-cell"><span class="plk-lab">'+kEsc(c[0])+'</span> <span class="plk-fig">'+kEsc(c[1])+'</span> <span class="plk-cap">'+kEsc(c[2])+'</span></li>'}).join('')+'</ul>';if(frame)h+='<p class="plk-close">'+kEsc(PC)+'</p>';w.innerHTML=h;host.appendChild(w);return w}
kitPlk(kSlot(),4,true);
